// Generates public/data/*.json from the CSVs in the sibling data repository.
//
//   node scripts/data/build-datasets.mjs
//
// The data repository is the single source of truth. The JSON committed under
// public/data/ is a build artifact, regenerated by this script whenever the CSVs
// change, so the site can deploy without access to the sibling checkout.
//
//   ../historical-monetary-data  https://github.com/MiguelPuntoEs/historical-monetary-data

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const SITE = join(here, "..", "..");
const DATA = join(SITE, "..", "historical-monetary-data");
const CONT = join(DATA, "continental-dollar");
const GREEN = join(DATA, "greenbacks");
const OUT = join(SITE, "public", "data");

/** Parse a CSV whose leading `#` lines are provenance comments. */
function readCsv(path) {
  const raw = readFileSync(path, "utf8").split(/\r?\n/);
  const notes = [];
  let i = 0;
  while (i < raw.length && raw[i].startsWith("#")) {
    notes.push(raw[i].replace(/^#\s?/, ""));
    i++;
  }
  const header = splitRow(raw[i++]);
  const rows = [];
  for (; i < raw.length; i++) {
    if (!raw[i].trim()) continue;
    const cells = splitRow(raw[i]);
    const o = {};
    header.forEach((h, k) => (o[h] = cells[k] ?? ""));
    rows.push(o);
  }
  return { notes, header, rows };
}

/** Minimal RFC-4180 split: handles quoted cells containing commas. */
function splitRow(line) {
  const out = [];
  let cur = "";
  let q = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') {
      if (q && line[i + 1] === '"') { cur += '"'; i++; } else q = !q;
    } else if (c === "," && !q) { out.push(cur); cur = ""; }
    else cur += c;
  }
  out.push(cur);
  return out.map((s) => s.trim());
}

const num = (v) => (v === "" || v == null ? null : Number(v));
const MONTHS = ["January","February","March","April","May","June",
                "July","August","September","October","November","December"];

function write(name, payload) {
  if (!existsSync(OUT)) mkdirSync(OUT, { recursive: true });
  writeFileSync(join(OUT, name), JSON.stringify(payload));
  const n = Array.isArray(payload.rows) ? payload.rows.length : "—";
  console.log(`  ${name.padEnd(34)} ${String(n).padStart(5)} rows`);
}

// ─── Continental dollar ────────────────────────────────────────────────────────

function continentalScales() {
  const { rows } = readCsv(join(CONT, "data/published/state_depreciation_scales.csv"));
  const states = ["massachusetts","pennsylvania_statute","new_jersey","delaware",
                  "maryland","virginia","north_carolina"];
  return {
    id: "continental-state-scales",
    title: "State scales of depreciation, 1777–1781",
    unit: "Continental dollars per specie dollar",
    source:
      "House Doc. No. 107 (1828), pp. 30–33 — reissued as American State Papers, Finance V. " +
      "Pennsylvania from the enacted statute: Act of 3 April 1781, ch. CMXXXV, sec. IV, " +
      "Statutes at Large of Pennsylvania x. 286–87.",
    series: states.map((s) => ({
      key: s,
      label: s === "pennsylvania_statute"
        ? "Pennsylvania (statute)"
        : s.split("_").map((w) => w[0].toUpperCase() + w.slice(1)).join(" "),
    })),
    rows: rows.map((r) => {
      const o = { date: r.date };
      states.forEach((s) => (o[s] = num(r[s])));
      return o;
    }),
  };
}

function continentalQuotations() {
  const { rows } = readCsv(join(CONT, "data/published/phillips_1866_merchants_books.csv"));
  return {
    id: "continental-quotations",
    title: "Merchants' book quotations, Philadelphia and Virginia, 1777–1781",
    unit: "Continental dollars per specie dollar",
    source:
      "Phillips (1866), pp. 217–18, reproducing the tables in Webster, Political Essays " +
      "(1791), p. 501. Ranges are given as low/high; mid is their midpoint.",
    series: [
      { key: "philadelphia_mid", label: "Philadelphia" },
      { key: "virginia", label: "Virginia" },
    ],
    rows: rows.map((r) => ({
      date: r.date,
      philadelphia_low: num(r.philadelphia_low),
      philadelphia_high: num(r.philadelphia_high),
      philadelphia_mid: num(r.philadelphia_mid),
      virginia: num(r.virginia),
    })),
  };
}

function pennsylvaniaSources() {
  const { rows } = readCsv(join(CONT, "data/published/pennsylvania_scale_three_sources.csv"));
  const q = readCsv(join(CONT, "data/published/phillips_1866_merchants_books.csv"));
  const mkt = Object.fromEntries(q.rows.map((r) => [r.date, num(r.philadelphia_mid)]));
  return {
    id: "pennsylvania-three-sources",
    title: "Pennsylvania's scale: statute against two printed compilations",
    unit: "Continental dollars per specie dollar",
    source:
      "Statute: Act of 3 April 1781, ch. CMXXXV, sec. IV, Statutes at Large of Pennsylvania " +
      "x. 286–87. American State Papers: House Doc. No. 107 (1828), p. 32. " +
      "Webster: Political Essays (1791), p. 501.",
    series: [
      { key: "statute_1781_act", label: "Enacted statute" },
      { key: "american_state_papers", label: "American State Papers" },
      { key: "webster_1791", label: "Webster (1791)" },
      { key: "philadelphia_market", label: "Philadelphia" },
    ],
    rows: rows.map((r) => {
      const s = num(r.statute_1781_act);
      const a = num(r.american_state_papers);
      const w = num(r.webster_1791);
      const vals = [s, a, w].filter((v) => v != null);
      return {
        date: r.date,
        statute_1781_act: s,
        american_state_papers: a,
        webster_1791: w,
        philadelphia_market: mkt[r.date] ?? null,
        disagree: new Set(vals).size > 1 || vals.length < 3,
      };
    }),
  };
}

// ─── Greenbacks ────────────────────────────────────────────────────────────────

function goldMonthly() {
  const { rows } = readCsv(join(GREEN, "data/mitchell_appendix_a_table1_gold_prices_1862_1865.csv"));
  return {
    id: "greenback-gold-monthly",
    title: "Gold price of $100 in paper currency, New York, 1862–1865",
    unit: "Gold dollars per $100 paper currency",
    source: "Wesley C. Mitchell, A History of the Greenbacks (1903), Appendix A, Table 1, pp. 423–24.",
    series: [
      { key: "highest", label: "Highest" },
      { key: "average", label: "Average" },
      { key: "lowest", label: "Lowest" },
    ],
    rows: rows.map((r) => ({
      date: `${r.year}-${String(MONTHS.indexOf(r.month) + 1).padStart(2, "0")}`,
      highest: num(r.highest),
      average: num(r.average),
      lowest: num(r.lowest),
    })),
  };
}

function moneyStock() {
  const { rows } = readCsv(join(GREEN, "data/Cj26-41_money_stock_1859_1866.csv"));
  const M = { Jan:1, Feb:2, Mar:3, Apr:4, May:5, Jun:6, Jul:7, Aug:8, Sep:9, Oct:10, Nov:11, Dec:12 };
  return {
    id: "greenback-money-stock",
    title: "Stock of money and components, 1859–1866",
    unit: "Millions of dollars",
    source:
      "Historical Statistics of the United States, Millennial Edition, Table Cj26-41 " +
      "(Friedman, Schwartz and Mitchell; contributed by Hugh Rockoff). Cj26 is the stock " +
      "of money excluding interest-bearing currency; Cj34 is non-interest-bearing " +
      "government currency, mostly greenbacks; Cj29 is the total stock of specie at face " +
      "value. From June 1861 to November 1864 the figures cover the Northern states only.",
    series: [
      { key: "Cj26", label: "Money stock" },
      { key: "Cj34", label: "Government currency (greenbacks)" },
      { key: "Cj29", label: "Specie, total stock" },
    ],
    rows: rows
      .filter((r) => r.Year && r.Month)
      .map((r) => ({
        date: `${r.Year}-${String(M[r.Month] ?? 1).padStart(2, "0")}`,
        Cj26: num(r.Cj26), Cj34: num(r.Cj34), Cj29: num(r.Cj29),
      })),
  };
}

// ─── run ───────────────────────────────────────────────────────────────────────

for (const [name, path] of [["continental-dollar", CONT], ["greenbacks", GREEN]]) {
  if (!existsSync(path)) {
    console.error(`\n  Missing dataset: ${name} (expected at ${path})`);
    console.error("  Clone historical-monetary-data alongside this site, then re-run.\n");
    process.exit(1);
  }
}

console.log("Building datasets from historical-monetary-data:\n");
write("continental-state-scales.json", continentalScales());
write("continental-quotations.json", continentalQuotations());
write("pennsylvania-three-sources.json", pennsylvaniaSources());
write("greenback-gold-monthly.json", goldMonthly());
write("greenback-money-stock.json", moneyStock());
console.log("\nWrote public/data/. Commit the JSON: it is what the site deploys.");
